#!/usr/bin/env python3
import hashlib,json,pathlib
root=pathlib.Path(__file__).resolve().parents[1]; f=json.loads((root/'FREEZE.json').read_text()); r=json.loads((root/'results/A01/RAW.json').read_text())
checks={'raw_preserved_and_xvfb_clean':(root/'results/A01/RAW.json').is_file() and r.get('cleanup',{}).get('xvfb_exit')==0,'candidate_harness_assertion_failed_as_reported':r.get('status')=='STOP' and any('AttributeError' in x for x in r.get('errors',[])),'source_hashes_match':all(hashlib.sha256((root/'SOURCE'/n).read_bytes()).hexdigest()==h for n,h in f['source_sha256'].items()),'candidate_hash_match':hashlib.sha256((root/'SOURCE/candidate.py').read_bytes()).hexdigest()==f['candidate_sha256'],'child_sigkill_and_active_key':r.get('worker_returncode')==-9 and r.get('key_down_before_kill') is True,'eof_and_owner_close':any(x.get('event')=='executor_channel_eof' for x in (r.get('supervisor_events') or [])) and type(r.get('owner_close_returned_ns')) is int,'owner_keyup_and_xstate_recorded':type(r.get('owner_release_record')) is dict and r['owner_release_record'].get('verified') is True and r.get('key_up_after_owner_close') is True,'independent_release_event_observed':type(r.get('key_release_after_kill')) is dict and r['key_release_after_kill'].get('type')==3}
out={'schema':'v39-executor-hardkill-supervised-a02-audit-v1','decision':'PASS_METHOD_SCOPED' if all(checks.values()) else 'STOP','checks':checks,'errors':r.get('errors'),'candidate_harness_status':r.get('status')}; (root/'AUDITOR/audit.json').write_text(json.dumps(out,indent=2,sort_keys=True)+'\n'); print(json.dumps(out,sort_keys=True))
